// Две роли (генератор не умеет) · spec: specs/location-map.md 3.1 · кейс .qa/tests/location-map/MAP-01.md
// Геолокация эмулируется; Date Now не включается; в конце шаринг выкл., возраст возвращён, сессии сохранены.
import { test, expect } from '../../fixtures';
import { enableSharing, disableSharing } from './map-helpers';
import { setupPair, teardownPair, pinOf, USER2_NAME, type Pair } from './pair-helpers';

test.describe('מסך מפת זמן אמת', () => {
  test.describe.configure({ timeout: 240_000 });
  test('включивший шаринг появляется на открытой карте другого без обновления, выключивший — пропадает @iphone @data (#0f19c0)', async ({ asUser }) => {
    let p: Pair | undefined;
    try {
      p = await setupPair(asUser, false);
      const { free, user2 } = p;
      await expect(free.getByText('אני', { exact: true })).toBeVisible();
      await expect(pinOf(free, USER2_NAME)).toHaveCount(0);
      // Карта free больше не перезагружается — считаем переходы страницы.
      let navigations = 0;
      free.on('framenavigated', (f) => { if (f === free.mainFrame()) navigations++; });

      // user2 включает шаринг → её пин появляется у free без обновления (Р1, Р2, AC 1; факт r9 ≈ 1.3 с — ждём до 15 с).
      await enableSharing(user2);
      await expect(pinOf(free, USER2_NAME)).toBeVisible({ timeout: 15_000 });
      await expect(free.getByText(/בקרבתך/).first()).toBeVisible();

      // user2 выключает → пин пропадает у free без обновления (AC 9).
      await disableSharing(user2);
      await expect(pinOf(free, USER2_NAME)).toHaveCount(0, { timeout: 15_000 });
      expect(navigations, 'карта free не перезагружалась').toBe(0);
    } finally {
      await teardownPair(p);
    }
  });
});
